// Check which feeds failed or returned 0 items
const items = $input.all();
const broken = [];
const healthy = [];

for (const item of items) {
  const name = item.json.feed_name || item.json.name || 'Unknown';
  if (item.json.error || !item.json.title) {
    broken.push(name);
  } else {
    healthy.push(name);
  }
}

if (broken.length === 0) {
  return [{ json: { allHealthy: true, message: `All ${healthy.length} feeds healthy.` } }];
}

return [{
  json: {
    allHealthy: false,
    brokenCount: broken.length,
    healthyCount: healthy.length,
    brokenFeeds: broken,
    message: `${broken.length} feed(s) broken: ${broken.join(', ')}`
  }
}];

